const videos={incline:'Bc_BTtk8J88',bench:'SHsUIZiNdeY',shoulder:'Gu1t7X2yq4M',lateral:'ENsp0DEryrM',pull:'SALxEARiMkw',pullup:'K81-SLUFo9c',face:'eIq5CB9JfKE',curl:'BJ6UVAUUJIs',deadlift:'hCDzSR6bW10',rdl:'5zmlnbWb-g4',squat:'nEQQle9-0NA',pushup:'14D-2c9kvVw'};
function videoFor(name){const n=name.toLowerCase();if(n.includes('face pull'))return videos.face;if(n.includes('push-up'))return videos.pushup;if(n.includes('romanian'))return videos.rdl;if(n.includes('squat'))return videos.squat;if(n.includes('pull-up')||n.includes('pulldown'))return n.includes('pull-up')?videos.pullup:videos.pull;if(n.includes('curl'))return videos.curl;if(n.includes('deadlift')||n.includes('carry')||n.includes('lunge')||n.includes('leg'))return videos.deadlift;if(n.includes('lateral'))return videos.lateral;if(n.includes('shoulder')||n.includes('landmine'))return videos.shoulder;if(n.includes('press'))return n.includes('incline')?videos.incline:videos.bench;if(n.includes('row'))return videos.pullup;return videos.pushup}
let selected=Number(localStorage.getItem('f5-day')||0);let completed=JSON.parse(localStorage.getItem('f5-completed')||'{}');
const weekStrip=document.querySelector('#weekStrip'),list=document.querySelector('#exerciseList');
function renderDays(){weekStrip.innerHTML=plan.map((d,i)=>`<button class="day-card ${i===selected?'active':''}" data-day="${i}"><small>DAY ${i+1}</small><strong>${d.name}</strong><span>${d.time}</span></button>`).join('');weekStrip.querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=+b.dataset.day;localStorage.setItem('f5-day',selected);render()})}
function renderSession(){const d=plan[selected],key='d'+selected,done=completed[key]||[];document.querySelector('#todayLabel').textContent=`TODAY · ${d.name.toUpperCase()}`;document.querySelector('#sessionKicker').textContent=`DAY ${selected+1} · ${d.name.toUpperCase()}`;document.querySelector('#sessionTitle').textContent=d.focus;document.querySelector('#sessionMeta').textContent=`~${d.time} · ${d.items.reduce((n,x)=>n+Number(x[1].match(/\d+/)[0]),0)} working sets`;list.innerHTML=d.items.map((x,i)=>`<article class="exercise ${done.includes(i)?'done':''}"><span class="exercise-index">0${i+1}</span><div><h3>${x[0]}</h3><p>${x[2]}</p></div><div class="sets">${x[1]}</div><button class="clip-button" data-clip="${i}">Watch form</button><button class="done-button" data-done="${i}" aria-label="Mark complete">${done.includes(i)?'✓':'○'}</button></article>`).join('');list.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>toggleDone(+b.dataset.done));list.querySelectorAll('[data-clip]').forEach(b=>b.onclick=()=>openClip(+b.dataset.clip));updateProgress()}
function toggleDone(i){const key='d'+selected,arr=completed[key]||[];completed[key]=arr.includes(i)?arr.filter(x=>x!==i):[...arr,i];localStorage.setItem('f5-completed',JSON.stringify(completed));renderSession()}
function updateProgress(){const n=(completed['d'+selected]||[]).length,total=plan[selected].items.length;document.querySelector('#progressText').textContent=`${n} / ${total} complete`;document.querySelector('#progressBar').style.width=`${n/total*100}%`}
function render(){renderDays();renderSession()}
const clip=document.querySelector('#clipDialog');let clipTicker,clipCutoff;function stopClip(){clearInterval(clipTicker);clearTimeout(clipCutoff);document.querySelector('#clipVideo').src=''}function playFocusedMinute(id,start=0){stopClip();let remaining=60;const timer=document.querySelector('#clipTimer');timer.textContent='1:00 · FOCUSED CLIP';document.querySelector('#clipVideo').src=`https://www.youtube-nocookie.com/embed/${id}?start=${start}&end=${start+60}&autoplay=1&controls=0&disablekb=1&fs=0&iv_load_policy=3&rel=0&modestbranding=1`;clipTicker=setInterval(()=>{remaining-=1;timer.textContent=remaining>0?`0:${String(remaining).padStart(2,'0')} · FOCUSED CLIP`:'PREVIEW COMPLETE';if(remaining<=0)clearInterval(clipTicker)},1000);clipCutoff=setTimeout(()=>{document.querySelector('#clipVideo').src='';timer.textContent='PREVIEW COMPLETE · FULL LESSON BELOW'},60000)}function openClip(i){const x=plan[selected].items[i],id=videoFor(x[0]);document.querySelector('#clipTitle').textContent=x[0];document.querySelector('#clipMuscle').textContent=x[2].toUpperCase()+' · QUICK FORM LESSON';playFocusedMinute(id,0);document.querySelector('#youtubeLink').href=`https://www.youtube.com/watch?v=${id}`;document.querySelector('#cueGrid').innerHTML=x[3].map((c,j)=>`<div><strong>${['SET UP','PERFORM','AVOID'][j]}</strong>${c}</div>`).join('');clip.showModal()}
document.querySelector('#closeClip').onclick=()=>{stopClip();clip.close()};clip.addEventListener('close',stopClip);document.querySelector('#startBtn').onclick=()=>document.querySelector('#session').scrollIntoView();document.querySelector('#swapDayBtn').onclick=()=>document.querySelector('.week-section').scrollIntoView();
const settings=document.querySelector('#settingsDialog');document.querySelector('#settingsBtn').onclick=()=>settings.showModal();document.querySelector('#closeSettings').onclick=()=>settings.close();document.querySelector('#profileForm').onsubmit=e=>{e.preventDefault();const p={weight:weightInput.value,height:heightInput.value,goal:goalInput.value,experience:experienceInput.value};localStorage.setItem('f5-profile',JSON.stringify(p));document.querySelector('.hero-copy').innerHTML=`A five-day, form-first split for your current profile: <strong>${p.weight} kg</strong>, <strong>${p.height} cm</strong>. Goal: <strong>${p.goal.toLowerCase()}</strong>.`;settings.close()};
const saved=JSON.parse(localStorage.getItem('f5-profile')||'null');if(saved){weightInput.value=saved.weight;heightInput.value=saved.height;goalInput.value=saved.goal;experienceInput.value=saved.experience;document.querySelector('.hero-copy').innerHTML=`A five-day, form-first split for your current profile: <strong>${saved.weight} kg</strong>, <strong>${saved.height} cm</strong>. Goal: <strong>${saved.goal.toLowerCase()}</strong>.`}render();
const mobility=[['BAND','Band pull-apart','Hold the band at chest height. Pull it apart without shrugging, then return slowly.','10 slow reps','JObYtU7Y7ag',25],['BAND','Banded lat stretch','Anchor the band high, sit your hips back, and breathe into the long side of your torso.','45 seconds','7dT4KHtMM-A',30],['BAND','Shoulder pass-through','Use a wide grip and a very light band. Travel only through a comfortable, pain-free arc.','8 slow reps','NtaPROZOcmM',20],['KETTLEBELL','Kettlebell halo','Hold a light bell by the horns and circle it slowly around your head without flaring your ribs.','5 each way'],['KETTLEBELL','Goblet squat pry','Hold a light bell, settle into a comfortable squat, and gently shift side to side.','45 seconds'],['KETTLEBELL','Half-kneeling hip shift','Use the bell as a counterbalance. Tuck the pelvis gently and shift forward without arching.','30 sec each']];
document.querySelector('#mobilityGrid').innerHTML=mobility.map((m,i)=>`<article class="mobility-card"><span class="tool">${m[0]}</span><h3>${m[1]}</h3><p>${m[2]}</p><div class="mobility-actions"><button class="timer-button" data-timer="${i}" data-label="${m[3]}">${m[3]} · Start</button>${m[4]?`<button class="mobility-video" data-mobility-video="${i}">▶ Watch 1 min</button>`:''}</div></article>`).join('');
document.querySelectorAll('[data-timer]').forEach(button=>button.onclick=()=>{if(button.dataset.running)return;if(button.dataset.label.includes('reps')||button.dataset.label.includes('each way')){button.classList.toggle('running');button.textContent=button.classList.contains('running')?'Done ✓':`${button.dataset.label} · Start`;return}button.dataset.running='1';button.classList.add('running');let seconds=button.dataset.label.includes('45')?45:30;button.textContent=`${seconds} sec · Breathe`;const timer=setInterval(()=>{seconds-=1;button.textContent=seconds>0?`${seconds} sec · Breathe`:'Done ✓';if(seconds<=0){clearInterval(timer);delete button.dataset.running}},1000)});
document.querySelectorAll('[data-feel]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-feel]').forEach(x=>x.classList.remove('active'));button.classList.add('active');const notes={Low:'Keep it gentle today: choose two mobility moves and reduce your working load.',Okay:'Ease in with three mobility moves, then let the warm-up sets guide you.',Ready:'Great. Warm up with intention and keep one or two clean reps in reserve.'};document.querySelector('#feelNote').textContent=notes[button.dataset.feel]});
document.querySelectorAll('[data-mobility-video]').forEach(button=>button.onclick=()=>{const m=mobility[+button.dataset.mobilityVideo],id=m[4],start=m[5];document.querySelector('#clipTitle').textContent=m[1];document.querySelector('#clipMuscle').textContent='BAND MOBILITY · RELEVANT 60-SECOND SEGMENT';playFocusedMinute(id,start);document.querySelector('#youtubeLink').href=`https://www.youtube.com/watch?v=${id}&t=${start}s`;document.querySelector('#cueGrid').innerHTML=`<div><strong>SET UP</strong>Use a light band and a pain-free range.</div><div><strong>MOVE</strong>${m[2]}</div><div><strong>BREATHE</strong>Slow exhale; never force the stretch.</div>`;clip.showModal()});
